const ACCOUNT_KEY = 'sutura:account:v1';
const SESSION_KEY = 'sutura:session:v1';
const LANGUAGE_KEY = 'sutura:language:v1';
const ITERATIONS = 160000;
const VOICE_LOCALE = { fr: 'fr-FR', wo: 'wo-SN', en: 'en-US' };

function read(key, fallback) {
  try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback; } catch { return fallback; }
}
function write(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* storage may be unavailable */ } }
function uid() { return crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function dateKey(offset = 0) { const d = new Date(); d.setDate(d.getDate() + offset); return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10); }
function day(date, options = { day: 'numeric', month: 'short' }) { return date ? new Intl.DateTimeFormat('fr-FR', options).format(new Date(`${date}T12:00:00`)) : ''; }
function cfa(value) { return `${new Intl.NumberFormat('fr-FR').format(Number(value || 0))} FCFA`; }
function clean(text = '') { return text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim(); }
function initials(name = '') { return name.split(/\s+/).filter(Boolean).slice(0, 2).map((p) => p[0]?.toUpperCase()).join('') || 'SU'; }
function friendlyName(username = '') { if (username === 'awa.demo') return 'Awa Diop'; return username.replace(/[._-]+/g, ' ').trim().split(/\s+/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(' ') || 'Ami'; }

