function useLocal(username, section, fallback) {
  const key = `sutura:data:${username}:${section}`;
  const [value, setValue] = useState(() => read(key, fallback));
  useEffect(() => write(key, value), [key, value]);
  return [value, setValue];
}
async function verifier(password, saltHex, iterations = ITERATIONS) {
  if (!globalThis.crypto?.subtle) throw new Error('secure-context');
  const salt = new Uint8Array(saltHex.match(/.{1,2}/g).map((v) => parseInt(v, 16)));
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations, hash: 'SHA-256' }, key, 256);
  return Array.from(new Uint8Array(bits), (v) => v.toString(16).padStart(2, '0')).join('');
}
function speak(text, language = 'fr', preference = 'feminine') {
  if (!('speechSynthesis' in window) || !('SpeechSynthesisUtterance' in window)) return false;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  const locale = VOICE_LOCALE[language] || VOICE_LOCALE.fr;
  const voices = window.speechSynthesis.getVoices();
  const sameLanguage = voices.filter((item) => item.lang?.toLowerCase().startsWith(locale.slice(0, 2)));
  const feminineName = /(female|feminine|woman|samantha|victoria|ava|jenny|zira|aria|susan|denise|hortense|julie|amelie|amélie|marie|alice|audrey|celine|céline|claire|lea|léa|marisol|monica|sara|sonia|helena|siri)/i;
  const voice = (preference === 'feminine' ? sameLanguage.find((item) => feminineName.test(item.name || '') || item.gender === 'female') : null)
    || sameLanguage[0]
    || voices.find((item) => item.lang?.toLowerCase().startsWith('fr'));
  utterance.lang = voice?.lang || (language === 'wo' ? 'fr-SN' : locale);
  if (voice) utterance.voice = voice;
  utterance.rate = 0.93;
  utterance.pitch = preference === 'feminine' ? 1.08 : 1;
  window.speechSynthesis.speak(utterance);
  return true;
}

export default function App() {
  const [account, setAccount] = useState(() => read(ACCOUNT_KEY, null));
  const [user, setUser] = useState(() => {
    const saved = read(ACCOUNT_KEY, null), session = sessionStorage.getItem(SESSION_KEY);
    return saved && session && clean(saved.username) === clean(session) ? saved.username : null;
  });
  const [language, setLanguage] = useState(() => localStorage.getItem(LANGUAGE_KEY) || 'fr');
  const [demo, setDemo] = useState(false);
  const changeLanguage = (value) => { setLanguage(value); try { localStorage.setItem(LANGUAGE_KEY, value); } catch { /* noop */ } };
  const authenticate = (username, newAccount = null, isDemo = false) => {
    if (newAccount) { write(ACCOUNT_KEY, newAccount); setAccount(newAccount); }
    if (isDemo) sessionStorage.removeItem(SESSION_KEY); else sessionStorage.setItem(SESSION_KEY, username);
    setDemo(isDemo); setUser(username);
  };
  const signOut = () => { sessionStorage.removeItem(SESSION_KEY); setDemo(false); setUser(null); };
  const resetAccount = () => { localStorage.removeItem(ACCOUNT_KEY); sessionStorage.removeItem(SESSION_KEY); setAccount(null); setUser(null); };
  if (!user) return <AuthScreen account={account} language={language} onLanguage={changeLanguage} onAuthenticated={authenticate} onReset={resetAccount} />;
  return <Workspace key={`${user}-${demo}`} username={user} isDemo={demo} language={language} onLanguage={changeLanguage} onSignOut={signOut} />;
}

